import logging
import time
from functools import wraps

log = logging.getLogger(__name__)


def retry(attempts=3, base_delay=0.5, backoff=2.0, max_delay=30.0, exceptions=(Exception,)):
    """Re-run the wrapped function when it raises, with exponential backoff.

    The delay before attempt n is base_delay * backoff ** (n - 1), capped at
    max_delay. The exception from the final attempt propagates to the caller.
    """
    if attempts < 1:
        raise ValueError("attempts must be at least 1")

    def decorate(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            delay = base_delay
            for attempt in range(1, attempts + 1):
                try:
                    return func(*args, **kwargs)
                except exceptions as exc:
                    if attempt == attempts:
                        log.warning(
                            "%s failed on final attempt %d/%d: %s",
                            func.__name__, attempt, attempts, exc,
                        )
                        raise
                    log.info(
                        "%s failed on attempt %d/%d (%s); retrying in %.2fs",
                        func.__name__, attempt, attempts, exc, delay,
                    )
                    time.sleep(delay)
                    delay = min(delay * backoff, max_delay)

        return wrapper

    return decorate
